// Stripe on the business's own API key: every operation of Stripe's REST API. actions.json is generated by
// `bun scripts/openapi-actions.ts stripe`; every event Stripe has starts automations by webhook (triggers.ts).
import { z } from "zod";
import { AppFile, AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, stripeVersion, triggers, unwatch, wanted, watch } from "./triggers";

const api: Api = {
  name: "Stripe",
  base: "https://api.stripe.com",
  tokenHelp: "dashboard.stripe.com/apikeys",
  auth: (key) => ({ Authorization: `Bearer ${key}`, "Stripe-Version": stripeVersion }),
};

const GET = (path: string) => ({ method: "GET", path, query: [], headers: [] });

export const stripe: OwnApp = {
  app: "stripe",
  name: "Stripe",
  logo: "/logos/stripe.svg",
  keyField: {
    label: "Secret or restricted key",
    help: "dashboard.stripe.com/apikeys → copy the secret key, or create a restricted key with the permissions Emplio should have. Automations also need Webhook Endpoints write and Events read.",
    placeholder: "sk_live_... or rk_live_...",
  },
  async check(key) {
    const test = key.includes("_test_") ? " (test mode)" : "";
    try {
      const me = (await call(api, key, GET("/v1/account"), {})) as { id: string; email?: string; settings?: { dashboard?: { display_name?: string } }; business_profile?: { name?: string } };
      return `${me.settings?.dashboard?.display_name || me.business_profile?.name || me.email || me.id}${test}`;
    } catch (error) {
      // a restricted key may not be allowed to read the account; it's still a good key
      if (error instanceof AppsError && !error.expired && error.message.endsWith("(403)")) return;
      throw error;
    }
  },
  push: {
    events,
    triggers,
    start: (key, connection, event) => watch(api, key, connection, event),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery, key) => receive(api, delivery, key),
    wanted,
  },
  actions: {
    ...(await specActions(new URL("./actions.json", import.meta.url), api)),
    download_file_contents: {
      description: "Download a file held by Stripe (a dispute's evidence, a report) to the computer.",
      readOnly: true,
      input: z.object({ file: z.string().describe("The file's id (file_...)") }),
      run: async (input: { file: string }, key: string) => {
        const got = await call({ ...api, base: "https://files.stripe.com" }, key, GET("/v1/files/{file}/contents"), input);
        return got instanceof AppFile ? new AppFile(input.file, got.mimetype, got.bytes) : got;
      },
    },
  },
};
